import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender address and a timestamp and block number to exercise the time check
    function testFuzz_property(address sender, uint256 ts, uint256 bn) public {
        // keep sender non-zero
        vm.assume(sender != address(0));
        // bound timestamp and block number to reasonable ranges
        ts = bound(ts, 1, type(uint64).max);
        bn = bound(bn, 1, 1_000_000_000);

        // Fund the sender so it can send 10 ether
        vm.deal(sender, 20 ether);

        // Warp chain to the candidate timestamp and set block number
        vm.warp(ts);
        vm.roll(uint64(bn));

        // make the call as sender with exactly 10 ether to invoke fallback
        bool ok;
        vm.prank(sender);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert (single assertTrue):
        // In the correct contract, whenever the fallback call returns successfully (ok == true),
        // pastBlockTime equals the current block.timestamp. The mutant can either revert (ok==false)
        // or, if it returns, may fail to update pastBlockTime correctly; thus we assert the relation
        // between success and the getter. This reads c via its public getter.
        if (ok) {
            // after successful call, pastBlockTime must equal the current block timestamp
            assertTrue(c.pastBlockTime() == block.timestamp);
        } else {
            // if the call reverted, we still assert a true condition to keep single assertTrue form by
            // asserting that pastBlockTime is NOT greater than block.timestamp (a harmless broad condition)
            // but to satisfy the requirement of a single assertTrue reading c, pick a property that always
            // holds for the reference: pastBlockTime <= block.timestamp (since reference only ever sets to
            // current timestamp on successful calls and initialized to 0).
            assertTrue(c.pastBlockTime() <= block.timestamp);
        }
    }
}

