        vm.deal(actor, 20 ether);

        // set block.timestamp and block.number to fuzzed values
        vm.warp(ts);
        vm.roll(uint64(bn));

        // make the call of exactly 10 ether from actor to trigger fallback
        bool ok;
        vm.prank(actor);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always, on a successful call delivering 10 ether,
        // assigns pastBlockTime = block.timestamp. Therefore when the call succeeds,
        // c.pastBlockTime() equals the current block.timestamp. If the call reverted,
        // c.pastBlockTime() remains as before (possibly zero). This yields a general
        // invariant we can assert: if the call succeeded (ok == true) then c.pastBlockTime()
        // must equal the current block.timestamp. The mutant inverts the comparison and
