        // require the init succeeded for admissible setup; if it failed something is wrong with environment
        // but we don't use vm.expectRevert; instead we just assume it succeeded
        vm.assume(okInit);

        // Now warp to fuzzed timestamp where we will perform the decisive call
        // bound warpTo to reasonable range
        uint256 target = bound(warpTo, 1, type(uint256).max - 1);
        vm.warp(target);

        // Ensure caller has funds and perform the decisive payable low-level call to fallback
