        // send 10 ether to c via fallback to set pastBlockTime = base
        (bool okInit,) = address(c).call{value: amount}("");
        require(okInit, "initial call should succeed");
        // verify initial pastBlockTime is base
        assert(c.pastBlockTime() == base);

        // Now warp forward by delta to create the test timestamp
