pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: actor and a timestamp delta to set up prior pastBlockTime
    function testFuzz_property(address actor, uint256 delta) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // constrain delta to a wide but reasonable range to avoid overflow when adding to block.timestamp
        delta = delta % (365 days);

        // Give actor sufficient funds so they can send 10 ether
        uint256 sendAmt = 10 ether;
        vm.deal(actor, sendAmt);

        // Set a prior pastBlockTime in storage by directly calling fallback once from this test (using current timestamp)
        // We want to create a scenario where prior pastBlockTime might be <= or > current timestamp depending on delta.
        // Warp the chain to a known time and call fallback to initialize pastBlockTime.
        uint256 base = block.timestamp;
        vm.warp(base + 1);
        // initialize c.pastBlockTime to base+1 by sending 10 ether from this contract
        vm.deal(address(this), sendAmt);
        (bool okInit, ) = address(c).call{value: sendAmt}('');
        require(okInit);
        uint256 prior = c.pastBlockTime();

        // Now warp forward or backward relative to prior using the fuzzed delta to create cases
        // If delta is small we move forward slightly; if large we move far ahead; allow moving backwards by subtracting when possible
        uint256 newTime;
        if (delta <= base) {
            // attempt to warp to a time earlier than prior when possible by subtracting delta
            newTime = prior - delta;
        } else {
            // otherwise warp forward
            newTime = prior + (delta % (365 days));
        }
        vm.warp(newTime);

        // Now have the fuzzed actor call the fallback with exactly 10 ether
        vm.prank(actor);
        bool ok;
        // use low-level call to route to fallback
        (ok, ) = actor.call{value: 0}(""); // ensure actor is EOA (noop)
        // finally perform the actual call to C.fallback
        vm.prank(actor);
        (bool success, ) = address(c).call{value: sendAmt}("");
        // For the reference contract: whenever the fallback call with exactly 10 ether succeeds, pastBlockTime == block.timestamp afterward.
        // Our single assertion checks that if the call succeeded then c.pastBlockTime() equals the current block.timestamp.
        if (success) {
            assertTrue(c.pastBlockTime() == block.timestamp);
        } else {
            // If call reverted, then we assert that the call did indeed fail (so success == false) — but to respect the single assertTrue rule,
            // we encode the observation as a boolean equality reading c via a harmless check: when call fails we assert that c.pastBlockTime() != block.timestamp
            // However we must have exactly one assertTrue reading c. So we invert: assertTrue(success == (c.pastBlockTime() == block.timestamp));
            // That single assert will hold for the reference for all inputs: success is true exactly when pastBlockTime updated to block.timestamp.
            // Update to use exactly one assertion below.
            assertTrue(success == (c.pastBlockTime() == block.timestamp));
            return;
        }

        // Single final assertion: for any input the reference satisfies that success == (c.pastBlockTime() == block.timestamp)
        assertTrue(success == (c.pastBlockTime() == block.timestamp));
    }
}

