    // we fuzz a uint256 roll to set block.number and an address actor to be the caller
    function testFuzz_property(uint256 roll, address actor) public {
        // keep roll in a wide but realistic range
        vm.assume(roll > 0);
        // ensure actor is not zero address
        vm.assume(actor != address(0));

